CREATE OR REPLACE FUNCTION lf_ops.touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'lf_ops'
AS $function$
begin
  new.updated_at := now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.fn_lf_pre_ekb_clean_retry_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'extensions'
AS $function$
declare
  v_operation text;
  v_evidence_sha text;
  v_missing_gate bigint;
begin
  if new.status<>'PASS_CLEAN' then
    return new;
  end if;

  select operation_code into v_operation
  from public.lf_operation_execution
  where execution_id=new.execution_id;

  if not public.lf_pre_ekb_gate_consumer_v1(v_operation) then
    return new;
  end if;

  select r.id into v_missing_gate
  from public.lf_operation_gate_check_results r
  where r.execution_id=new.execution_id
    and r.check_status in ('FAIL','BLOCKED')
    and not exists (
      select 1
      from public.lf_eventos e
      where e.evento_tipo='REMEDIACION_GOBERNANZA'
        and e.created_by_execution_id=r.execution_id
        and e.origen='LF_PRE_EKB_GATE_AUTOPERSIST_V1'
        and e.payload->>'persistence_result'='EKB_PERSISTED'
        and (e.payload->>'gate_check_result_id')::bigint=r.id
    )
  order by r.id
  limit 1;

  if v_missing_gate is not null then
    raise exception 'BLOCKED_EKB_PERSISTENCE:GATE_CHECK_RESULT:%',v_missing_gate;
  end if;

  if tg_op='UPDATE'
     and (
       upper(old.status) like 'BLOCK%'
       or upper(old.status) like 'FAIL%'
       or upper(old.status) like 'RETURN%'
     ) then
    v_evidence_sha:=encode(
      extensions.digest(convert_to(coalesce(old.evidence_payload,'{}'::jsonb)::text,'UTF8'),'sha256'),
      'hex'
    );

    if not exists (
      select 1
      from public.lf_eventos e
      where e.evento_tipo='REMEDIACION_GOBERNANZA'
        and e.created_by_execution_id=new.execution_id
        and e.origen='LF_PRE_EKB_GATE_AUTOPERSIST_V1'
        and e.payload->>'persistence_result'='EKB_PERSISTED'
        and e.payload->'writer_receipt' is not null
        and exists (
          select 1
          from public.lf_operation_execution c
          where c.execution_id=e.payload->>'child_execution_id'
            and c.checkpoint_payload->>'finding_fingerprint'=e.payload->>'finding_fingerprint'
        )
        and e.payload->>'finding_fingerprint'=encode(
          extensions.digest(
            convert_to(new.execution_id||'|'||new.step_id||'|'||old.status||'|'||
              coalesce(
                nullif(old.evidence_payload->>'blocked_reason_code',''),
                nullif(old.evidence_payload->'blocking_codes'->>0,''),
                nullif(old.evidence_payload->'blocking_findings'->>0,''),
                old.status
              )||'|'||v_evidence_sha,'UTF8'
            ),
            'sha256'
          ),
          'hex'
        )
    ) then
      raise exception 'BLOCKED_EKB_PERSISTENCE:STEP_FAILURE:%',new.step_id;
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.fn_lf_pre_ekb_step_failure_autopersist_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_operation text;
  v_receipt jsonb;
  v_err text;
begin
  select operation_code into v_operation
  from public.lf_operation_execution
  where execution_id=new.execution_id;

  if not public.lf_pre_ekb_gate_consumer_v1(v_operation)
     or not (
       upper(new.status) like 'BLOCK%'
       or upper(new.status) like 'FAIL%'
       or upper(new.status) like 'RETURN%'
     ) then
    return new;
  end if;

  begin
    v_receipt:=public.lf_pre_ekb_step_failure_dispatch_v1(new.execution_id,new.step_id);
  exception when others then
    v_err:=sqlstate||':'||sqlerrm;

    insert into public.lf_eventos(
      evento_tipo,entidad_tipo,entidad_codigo,descripcion,severidad,payload,origen,created_by_execution_id
    ) values (
      'REMEDIACION_GOBERNANZA','LF_PRE_EKB_AUTOPERSIST','BLOCKED_EKB_PERSISTENCE',
      'Step failure is durable but EKB autopersistence failed; clean retry remains blocked',
      'WARN',
      jsonb_build_object(
        'evidence_schema_version','operational-event/v2',
        'execution_id',new.execution_id,
        'producer','LF_PRE_EKB_GATE_AUTOPERSIST_V1',
        'purpose','Persist fail-closed evidence that a durable non-pass step could not yet be written to EKB',
        'occurred_at',clock_timestamp(),
        'acceptance_declared',false,
        'persistence_result','BLOCKED_EKB_PERSISTENCE',
        'operation_code',v_operation,
        'step_id',new.step_id,
        'status',new.status,
        'evidence_ref',new.evidence_ref,
        'error',v_err
      ),
      'LF_PRE_EKB_GATE_AUTOPERSIST_V1',
      new.execution_id
    );

    return new;
  end;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_lf_operation_provenance_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_created_operation text;
  v_updated_operation text;
  v_created_status text;
  v_updated_status text;
  v_created_manifest jsonb;
  v_updated_manifest jsonb;
  v_validate_created boolean;
  v_validate_updated boolean;
  v_target_status text;
  v_created_bootstrap_allowed boolean := false;
  v_updated_bootstrap_allowed boolean := false;
  v_created_runtime_update_allowed boolean := false;
  v_updated_runtime_update_allowed boolean := false;
begin
  if tg_op = 'UPDATE' and new.operation_code is distinct from old.operation_code then
    raise exception 'LF_OPERATION_PROVENANCE_OPERATION_CODE_IMMUTABLE:%:%', old.operation_code, new.operation_code
      using errcode = '23514';
  end if;

  v_validate_created := tg_op = 'INSERT'
    or (tg_op = 'UPDATE' and new.created_by_execution_id is distinct from old.created_by_execution_id);
  v_validate_updated := tg_op = 'INSERT'
    or (tg_op = 'UPDATE' and new.updated_by_execution_id is distinct from old.updated_by_execution_id);

  if tg_table_name = 'lf_operation_registry' then
    v_target_status := new.status;
  else
    select r.status into v_target_status
    from public.lf_operation_registry r
    where r.operation_code = new.operation_code;
  end if;

  if v_validate_created then
    if new.created_by_execution_id is null or btrim(new.created_by_execution_id) = '' or new.created_by_execution_id = 'UNKNOWN' then
      raise exception 'LF_OPERATION_PROVENANCE_CREATED_EXECUTION_REQUIRED'
        using errcode = '23514';
    end if;

    select e.operation_code,e.status,e.manifest
      into v_created_operation,v_created_status,v_created_manifest
    from public.lf_operation_execution e
    where e.execution_id = new.created_by_execution_id;

    if v_created_operation is null then
      raise exception 'LF_OPERATION_PROVENANCE_CREATED_EXECUTION_MISSING:%', new.created_by_execution_id
        using errcode = '23503';
    end if;

    v_created_bootstrap_allowed :=
      v_created_operation = 'VULNERABILITY_COVERAGE_REPAIR_LF'
      and v_created_status = 'IN_PROGRESS'
      and coalesce((v_created_manifest->>'governance_bootstrap')::boolean,false) = true
      and v_created_manifest->>'bootstrap_operation_code' = new.operation_code
      and coalesce(v_created_manifest->>'bootstrap_status_ceiling','') = 'SANDBOX_ACTIVE'
      and v_target_status in ('SANDBOX_ACTIVE','CANDIDATO_READ_ONLY');

    v_created_runtime_update_allowed :=
      v_created_operation = 'ACTUALIZACION_RUNTIME_EJECUCION_PERFIL_LF'
      and v_created_status = 'IN_PROGRESS'
      and coalesce((v_created_manifest->>'runtime_update_governed')::boolean,false) = true
      and v_created_manifest->>'target_operation' = new.operation_code;

    if v_created_operation <> new.operation_code
       and not v_created_bootstrap_allowed
       and not v_created_runtime_update_allowed then
      raise exception 'LF_OPERATION_PROVENANCE_CREATED_SCOPE_MISMATCH:%:%:%',
        new.created_by_execution_id, v_created_operation, new.operation_code
        using errcode = '23514';
    end if;
  end if;

  if v_validate_updated and new.updated_by_execution_id is not null and btrim(new.updated_by_execution_id) <> '' then
    select e.operation_code,e.status,e.manifest
      into v_updated_operation,v_updated_status,v_updated_manifest
    from public.lf_operation_execution e
    where e.execution_id = new.updated_by_execution_id;

    if v_updated_operation is null then
      raise exception 'LF_OPERATION_PROVENANCE_UPDATED_EXECUTION_MISSING:%', new.updated_by_execution_id
        using errcode = '23503';
    end if;

    v_updated_bootstrap_allowed :=
      v_updated_operation = 'VULNERABILITY_COVERAGE_REPAIR_LF'
      and v_updated_status = 'IN_PROGRESS'
      and coalesce((v_updated_manifest->>'governance_bootstrap')::boolean,false) = true
      and v_updated_manifest->>'bootstrap_operation_code' = new.operation_code
      and coalesce(v_updated_manifest->>'bootstrap_status_ceiling','') = 'SANDBOX_ACTIVE'
      and v_target_status in ('SANDBOX_ACTIVE','CANDIDATO_READ_ONLY');

    v_updated_runtime_update_allowed :=
      v_updated_operation = 'ACTUALIZACION_RUNTIME_EJECUCION_PERFIL_LF'
      and v_updated_status = 'IN_PROGRESS'
      and coalesce((v_updated_manifest->>'runtime_update_governed')::boolean,false) = true
      and v_updated_manifest->>'target_operation' = new.operation_code;

    if v_updated_operation <> new.operation_code
       and not v_updated_bootstrap_allowed
       and not v_updated_runtime_update_allowed then
      raise exception 'LF_OPERATION_PROVENANCE_UPDATED_SCOPE_MISMATCH:%:%:%',
        new.updated_by_execution_id, v_updated_operation, new.operation_code
        using errcode = '23514';
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_lf_operation_registry_materialization_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_lifecycle_required boolean;
  v_required_steps integer;
  v_active_contracts integer;
  v_active_bindings integer;
  v_active_bound_judges integer;
begin
  if new.status <> 'PRODUCCION_CONTROLADA' then
    return new;
  end if;

  if tg_op = 'UPDATE' and new.status is not distinct from old.status then
    return new;
  end if;

  select exists (
    select 1
    from public.lf_operation_policy_bindings p
    where p.operation_code = new.operation_code
      and p.policy_role = 'GOVERNANCE_LIFECYCLE'
      and p.required = true
      and p.binding_status = 'ACTIVE'
  ) into v_lifecycle_required;

  if not v_lifecycle_required then
    return new;
  end if;

  select count(*) into v_required_steps
  from public.lf_operation_steps s
  where s.operation_code = new.operation_code and s.required = true;

  if v_required_steps = 0 then
    raise exception 'LF_OPERATION_MATERIALIZATION_REQUIRED_STEPS_MISSING:%', new.operation_code using errcode = '23514';
  end if;

  select count(*) into v_active_contracts
  from public.lf_operation_steps s
  join public.lf_operation_step_contracts c
    on c.operation_code = s.operation_code and c.step_order = s.step_order and c.step_id = s.step_id and c.status = 'ACTIVE_ENFORCEMENT'
  where s.operation_code = new.operation_code and s.required = true;

  if v_active_contracts <> v_required_steps then
    raise exception 'LF_OPERATION_MATERIALIZATION_CONTRACT_GAP:%:%:%', new.operation_code, v_active_contracts, v_required_steps using errcode = '23514';
  end if;

  select count(*), count(*) filter (where j.judge_code is not null)
    into v_active_bindings, v_active_bound_judges
  from public.lf_operation_steps s
  join public.lf_operation_step_judge_bindings b
    on b.operation_code = s.operation_code and b.step_order = s.step_order and b.step_id = s.step_id and b.status = 'ACTIVE_ENFORCEMENT'
  left join public.lf_operation_judges j
    on j.operation_code = b.operation_code and j.judge_code = b.judge_code and j.status = 'ACTIVE_ENFORCEMENT'
  where s.operation_code = new.operation_code and s.required = true;

  if v_active_bindings <> v_required_steps or v_active_bound_judges <> v_required_steps then
    raise exception 'LF_OPERATION_MATERIALIZATION_JUDGE_GAP:%:%:%:%', new.operation_code, v_active_bindings, v_active_bound_judges, v_required_steps using errcode = '23514';
  end if;

  return new;
end;
$function$

